const body = $input.first().json.body;

const required = ['essay_text', 'essay_title'];
const missing = required.filter(f => !body[f]);
if (missing.length) {
  return [{ json: { valid: false, error: `Missing: ${missing.join(', ')}` } }];
}

if (body.essay_text.trim().length < 200) {
  return [{ json: { valid: false, error: 'Essay text too short — minimum 200 characters' } }];
}

const validLevels = ['high_school', 'undergraduate', 'graduate', 'phd', 'professional'];
const academicLevel = validLevels.includes(body.academic_level) ? body.academic_level : 'undergraduate';

const validTypes = ['argumentative', 'analytical', 'expository', 'comparative', 'research', 'reflective', 'literature_review', 'case_study', 'other'];
const essayType = validTypes.includes(body.essay_type) ? body.essay_type : 'other';

return [{
  json: {
    valid: true,
    essayTitle: body.essay_title.trim(),
    essayText: body.essay_text.trim().slice(0, 10000),
    essayType,
    academicLevel,
    subject: body.subject || '',
    assignmentPrompt: (body.assignment_prompt || '').slice(0, 600),
    wordCount: body.essay_text.trim().split(/\s+/).length,
    targetWordCount: parseInt(body.target_word_count) || null,
    specificConcerns: (body.specific_concerns || '').slice(0, 400),
    citationStyle: body.citation_style || '',
    replyEmail: body.reply_email || null,
    requestedAt: new Date().toISOString()
  }
}];

